using System.Numerics;

namespace RayTracer.Rendering.Sky;

/// <summary>
/// Hosek and Wilkie (2012), "An Analytic Model for Full Spectral Sky-Dome
/// Radiance", RGB version: nine coefficients per channel, interpolated from
/// the authors' fitted tables (<see cref="HosekWilkieData"/>, generated by
/// <c>validation/gen_hosek_wilkie_data.py</c>) over turbidity (1-10), ground
/// albedo (0-1, per channel) and solar elevation, then
/// <code>
///   L(θ, γ) = (1 + A·e^(B/(cosθ + 0.01))) · (C + D·e^(Eγ) + F·cos²γ + G·χ(H, γ) + I·√cosθ) · L_M
///   χ(g, γ) = (1 + cos²γ) / (1 + g² − 2g·cosγ)^1.5
/// </code>
/// with θ the view's zenith angle, γ its angle to the sun and L_M the
/// channel's radiance scale. Checked against the authors' reference C code
/// (<c>HosekWilkieSkyTests</c>).
///
/// <para>The tables give radiance whose luminance is in W/(m²·sr) of the
/// photopic band: × 683 lm/W is nits, × 0.683 the kcd/m² of the relative
/// scale. The model holds for the sun above the horizon; below it the sky
/// stays at sunset. The sun's disc comes from <see cref="Atmosphere"/> with
/// the dust of the same turbidity.</para>
/// </summary>
public sealed class HosekWilkieSky : AnalyticSky
{
    /// <summary>Atmospheric turbidity, 1 (very clear) to 10 (hazy).</summary>
    public float Turbidity { get; }

    private readonly double[][] _config = new double[3][];
    private readonly double[] _radiance = new double[3];
    private readonly float _scale;

    public HosekWilkieSky(Vector3 sunDirToSun, float turbidity = 3f, Vector3? groundAlbedo = null,
                          float intensity = 1f, SkyUnits units = SkyUnits.Relative)
        : base(sunDirToSun, groundAlbedo ?? new Vector3(0.3f), intensity, units,
               new Atmosphere(dustDensity: Atmosphere.DustFromTurbidity(Math.Clamp(turbidity, 1f, 10f))))
    {
        Turbidity = Math.Clamp(turbidity, 1f, 10f);
        double elevation = Math.Asin(Math.Clamp(SunDirection.Y, 0f, 1f));
        var albedo = new[] { GroundAlbedo.X, GroundAlbedo.Y, GroundAlbedo.Z };
        var coeffs = new[] { HosekWilkieData.CoefficientsR, HosekWilkieData.CoefficientsG, HosekWilkieData.CoefficientsB };
        var rads = new[] { HosekWilkieData.RadianceR, HosekWilkieData.RadianceG, HosekWilkieData.RadianceB };
        for (int c = 0; c < 3; c++)
        {
            _config[c] = Cook(coeffs[c], 9, Turbidity, albedo[c], elevation);
            _radiance[c] = Cook(rads[c], 1, Turbidity, albedo[c], elevation)[0];
        }
        _scale = units == SkyUnits.Photometric ? 683f : 0.683f;
        Finish(units == SkyUnits.Photometric ? Atmosphere.SolarIlluminanceTop : Atmosphere.SolarIlluminanceTop / 1000f);
    }

    /// <summary>
    /// The model's raw RGB radiance (the reference code's output) toward view
    /// zenith angle <paramref name="theta"/> at angle <paramref name="gamma"/>
    /// from the sun, both in radians.
    /// </summary>
    internal Vector3 RawRadiance(double theta, double gamma)
        => new((float)(Evaluate(_config[0], theta, gamma) * _radiance[0]),
               (float)(Evaluate(_config[1], theta, gamma) * _radiance[1]),
               (float)(Evaluate(_config[2], theta, gamma) * _radiance[2]));

    protected override Vector3 Above(Vector3 dir)
    {
        double cosTheta = Math.Clamp(dir.Y, 0f, 1f);
        double cosGamma = Math.Clamp(Vector3.Dot(dir, SunDirection), -1f, 1f);
        return RawRadiance(Math.Acos(cosTheta), Math.Acos(cosGamma)) * _scale;
    }

    private static double Evaluate(double[] c, double theta, double gamma)
    {
        double cosT = Math.Cos(theta), cosG = Math.Cos(gamma);
        double expM = Math.Exp(c[4] * gamma);
        double rayM = cosG * cosG;
        double mieM = (1.0 + rayM) / Math.Pow(1.0 + c[8] * c[8] - 2.0 * c[8] * cosG, 1.5);
        double zenith = Math.Sqrt(Math.Max(0.0, cosT));
        return (1.0 + c[0] * Math.Exp(c[1] / (cosT + 0.01)))
             * (c[2] + c[3] * expM + c[5] * rayM + c[6] * mieM + c[7] * zenith);
    }

    /// <summary>
    /// The reference code's <c>CookConfiguration</c> / <c>CookRadianceConfiguration</c>:
    /// a quintic Bézier over the cube root of the normalised solar elevation,
    /// blended linearly in turbidity and albedo. Tables are laid out
    /// [albedo 2][turbidity 10][control point 6][<paramref name="width"/>].
    /// </summary>
    private static double[] Cook(double[] data, int width, float turbidity, float albedo, double elevation)
    {
        int ti = Math.Clamp((int)turbidity, 1, 10);
        double tr = turbidity - ti;
        double e = Math.Pow(elevation / (Math.PI / 2), 1.0 / 3.0);
        double u = 1 - e;
        var w = new[] { u * u * u * u * u, 5 * u * u * u * u * e, 10 * u * u * u * e * e,
                        10 * u * u * e * e * e, 5 * u * e * e * e * e, e * e * e * e * e };
        var o = new double[width];
        void Add(int alb, int turb, double weight)
        {
            if (weight == 0) return;
            int baseIndex = (alb * 10 + turb - 1) * 6 * width;
            for (int i = 0; i < width; i++)
            {
                double s = 0;
                for (int k = 0; k < 6; k++) s += w[k] * data[baseIndex + k * width + i];
                o[i] += weight * s;
            }
        }
        Add(0, ti, (1 - albedo) * (1 - tr));
        Add(1, ti, albedo * (1 - tr));
        if (ti < 10)
        {
            Add(0, ti + 1, (1 - albedo) * tr);
            Add(1, ti + 1, albedo * tr);
        }
        return o;
    }
}
